import React, { useEffect, useRef } from 'react';
import { BarChart3, TrendingUp, Zap, Gauge, Award, Layers } from 'lucide-react';
import ProductionChart from '../components/ProductionChart';
import EnergyCard from '../components/EnergyCard';
import HealthTrendChart from '../components/HealthTrendChart';

const AnalyticsPage = ({ defaultSection }) => {
  const prodRef = useRef(null);
  const energyRef = useRef(null);

  useEffect(() => {
    if (defaultSection === 'production' && prodRef.current) {
      prodRef.current.scrollIntoView({ behavior: 'smooth' });
    } else if (defaultSection === 'energy' && energyRef.current) {
      energyRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [defaultSection]);

  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <div className="page-title-group">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <h1>📊 Plant Performance & OEE Analytics</h1>
            <span className="badge badge-running" style={{ fontWeight: '800' }}>
              {defaultSection === 'production'
                ? 'Production Analytics'
                : defaultSection === 'energy'
                ? 'Energy Dashboard'
                : 'Overall OEE 96.4%'}
            </span>
          </div>
          <p>Comprehensive Plant Analytics for Energy Consumption, Machine Utilization, Production Output, and Downtime</p>
        </div>
      </div>

      {/* Top 4 Key Performance Metrics */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1.25rem', marginBottom: '1.75rem' }}>
        <div className="glass-card" style={{ padding: '1.25rem', border: defaultSection === 'oee' ? '2px solid #7C3AED' : undefined }}>
          <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '800' }}>OVERALL EQUIPMENT EFFICIENCY</div>
          <div style={{ fontSize: '1.8rem', fontWeight: '900', color: 'var(--accent-primary)', marginTop: '4px' }}>96.4%</div>
          <div style={{ fontSize: '0.74rem', color: 'var(--status-running)', marginTop: '4px', fontWeight: '700' }}>+1.8% vs Last Month</div>
        </div>

        <div className="glass-card" style={{ padding: '1.25rem', border: defaultSection === 'production' ? '2px solid #2563EB' : undefined }}>
          <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '800' }}>DAILY WEAVING YIELD</div>
          <div style={{ fontSize: '1.8rem', fontWeight: '900', color: 'var(--text-primary)', marginTop: '4px' }}>35,640 M</div>
          <div style={{ fontSize: '0.74rem', color: 'var(--status-running)', marginTop: '4px', fontWeight: '700' }}>Target: 34,000 M (Exceeded)</div>
        </div>

        <div className="glass-card" style={{ padding: '1.25rem', border: defaultSection === 'energy' ? '2px solid #059669' : undefined }}>
          <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '800' }}>SPECIFIC ENERGY RATE</div>
          <div style={{ fontSize: '1.8rem', fontWeight: '900', color: 'var(--text-primary)', marginTop: '4px' }}>0.42 kWh/M</div>
          <div style={{ fontSize: '0.74rem', color: 'var(--status-running)', marginTop: '4px', fontWeight: '700' }}>Eco-Rating Grade A+</div>
        </div>

        <div className="glass-card" style={{ padding: '1.25rem' }}>
          <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '800' }}>FIRST-CHOICE QUALITY</div>
          <div style={{ fontSize: '1.8rem', fontWeight: '900', color: 'var(--accent-primary)', marginTop: '4px' }}>99.1%</div>
          <div style={{ fontSize: '0.74rem', color: 'var(--text-muted)', marginTop: '4px', fontWeight: '700' }}>Zero Major Fabric Defects</div>
        </div>
      </div>

      {/* Charts Row */}
      <div ref={prodRef} style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '1.5rem', marginBottom: '1.75rem' }}>
        <ProductionChart />
        <HealthTrendChart />
      </div>

      {/* Energy Breakdown */}
      <div ref={energyRef} style={{ marginBottom: '1.75rem' }}>
        <EnergyCard />
      </div>
    </div>
  );
};

export default AnalyticsPage;
